with gaps as (select *, case when txn_time - lag(txn_time) over (partition by merchant order by txn_time, id) > interval '14' day then 1 else 0 end as new_group_flag from transactions), sessionized as (select *, sum(new_group_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as session_no from gaps) select s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.is_flagged, s.new_group_flag, s.session_no, (select min(x.amount) from transactions x where x.account_id = s.account_id) as min_transaction_amount from sessionized s order by txn_type nulls first, new_group_flag
